with deduped as (select * from (select *, row_number() over (partition by plan order by monthly_fee nulls first, id) as rn from subscriptions) t where rn = 1) select customer_id, case when monthly_fee >= 241 then 'LARGE' else 'SMALL' end as monthly_fee_tier, count(case when status = 'ACTIVE' then 1 end) as active_count, sum(case when status = 'CANCELLED' then monthly_fee else 0 end) as cancelled_monthly_fee, count(distinct status) as distinct_status from deduped group by 1, 2 having count(distinct status) >= 1
